647		powers, using $0\leq\eps\leq1$ and $\beta\leq b/4$, give
648		\[
649			\delta_G^{1/4}\leq HR,\qquad
650			\eps^{1/8}\leq HR,\qquad
651			(D/q)^{1/4}\leq HR,\qquad D/q\leq HR.
652		\]
653		Indeed, the fourth root of the sum defining $\delta_G/H$ is at most
654		$R$, while $H^{1/4}\leq H$, $D^{1/4}\leq D\leq H$,
655		$\eps^{1/8}\leq\eps^\beta$, and $q^{-1/4},q^{-1}\leq q^{-\beta}$.
656		Since $C^{1/4}\leq C$, subadditivity also gives
657		$\delta_P^{1/4}\leq3CHR$. Consequently,
658		\[
659			\delta_{\mathrm{ext}}
660			\leq C(3C+1)HR\leq4C^2HR=AD^aR\leq AD^AR.
661		\]
662		Thus $a'=A$ and $b'=\beta$ have the required properties.
663	\end{proof}
