392		There is a universal constant $C_{\mathrm{ext}}\geq1$. Set
393		\[
394			\delta_P^{\mathrm{ext}}=C_{\mathrm{ext}}B,
395			\qquad
396			\delta_{\mathrm{qld}}=C_{\mathrm{ext}}
397			\left((\delta_P^{\mathrm{ext}})^{1/4}+\frac{md}{q}\right).
398		\]
399		There exist unitaries $V_{\mathrm{A}}$ acting on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ and $V_{\mathrm{B}}$ acting on registers $\mathrm{B}\mathrm{B}'\mathrm{B}''$, such that the following hold.
400		\begin{enumerate}
401			\item There exists a state $\ket{\mathrm{aux}}$ on registers $\mathrm{A}\mathrm{A}'\mathrm{B}\mathrm{B}'$ such that
402			\[
403				\bigl\| V_{\mathrm{A}} \ot V_{\mathrm{B}} \ket{\hat{\psi}}_{\mathrm{A}\mathrm{A}'\mathrm{A}''\mathrm{B}\mathrm{B}'\mathrm{B}''} - \ket{\mathrm{aux}}_{\mathrm{A}\mathrm{A}'\mathrm{B}\mathrm{B}'} \ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathrm{A}''\mathrm{B}''} \bigr\|^2 \leq \delta_{\mathrm{qld}}\;.
